  if (method === "PATCH" && sessionMember) {
    return "session.write";
  }

  const promptRunCollection = PROMPT_RUN_COLLECTION_PATH.test(path);
  const promptRunEvents = PROMPT_RUN_EVENTS_PATH.test(path);
