    throw new Error("Runtime runner qualifier is invalid");
  }
  return decoded;
}

function validateResourceId(resourceId: string): void {
  if (!RESOURCE_ID_PATTERN.test(resourceId)) {
    throw new Error("Runtime resource ID is invalid");
  }
