        if not body:
            return
        try:
            payload = httpx.Response(status_code, content=body).json()
        except ValueError:
            raise SpritesProtocolError("Sprite network policy response is not valid JSON") from None
        if not isinstance(payload, dict) or payload.get("rules") != rules:
